const body = $input.first().json.body || $input.first().json;
const jenkinsfile = String(body.jenkinsfile || '').trim();
const projectName = body.projectName || 'projet';
const context     = body.context || {};
const owner  = String(body.owner  || '').trim();
const repo   = String(body.repo   || '').trim();
const branch = String(body.branch || 'main').trim();
const buildError = String(body.buildError || '').trim();
if (!jenkinsfile || jenkinsfile.length < 30) return [{ json: { error: 'INVALID_INPUT', message: 'Jenkinsfile vide ou trop court (min 30 caractères)' } }];
if (jenkinsfile.length > 60000) return [{ json: { error: 'TOO_LARGE', message: 'Jenkinsfile trop volumineux (max 60 Ko)' } }];

// ── SÉLECTION (régénération) ────────────────────────────────────────────────
// Source PRÉFÉRÉE (structurée) attendue du backend :
//   body.selection = { kept: [{ref,title}], excluded: [{ref,title}] }
// Fallback rétro-compatible : ancien texte prose context.notes (analyse initiale).
const selection = body.selection || context.selection || null;
const kept     = selection && Array.isArray(selection.kept)     ? selection.kept     : [];
const excluded = selection && Array.isArray(selection.excluded) ? selection.excluded : [];
const isRegen  = kept.length > 0 || excluded.length > 0;

const fmtList = (arr) => arr.length
  ? arr.map(i => `- [${i.ref || i.id || '?'}] ${(i.title || i.recommendation || '').toString().trim()}`).join('\n')
  : '- (aucune)';

const keptTxt  = fmtList(kept);
const exclTxt  = fmtList(excluded);
const exclRefs = excluded.map(i => i.ref || i.id || '?').join(', ') || '(aucune)';

// Bloc de contrainte injecté EN TÊTE du message (uniquement en régénération).
const selectionBlock = isRegen ? `
════════════════════════════════════════════════
CONTRAINTE DE SÉLECTION — PRIORITÉ ABSOLUE
════════════════════════════════════════════════
Ceci est une RÉGÉNÉRATION. Le développeur a examiné une analyse précédente et fait des
choix DÉLIBÉRÉS. Ce ne sont pas des oublis : ce sont des décisions à respecter à la lettre.

CORRECTIONS RETENUES (à appliquer dans le Jenkinsfile régénéré) :
${keptTxt}

CORRECTIONS ÉCARTÉES (STRICTEMENT INTERDITES — à ne jamais réintroduire) :
${exclTxt}

RÈGLES IMPÉRATIVES :
1. Le Jenkinsfile régénéré ne doit contenir AUCUNE des corrections écartées ci-dessus —
   ni sous une autre forme, ni sous un autre nom, ni dans un commentaire.
2. Même si une correction écartée est une bonne pratique DevSecOps standard (timeout,
   cleanWs, retry, quality gate, etc.), tu NE DOIS PAS l'ajouter. Ce n'est PAS une omission
   à corriger : le développeur l'a retirée CONSCIEMMENT. La réintroduire est une ERREUR,
   pas une amélioration.
3. Ne renumérote jamais une correction écartée comme si elle était retenue, et n'ajoute
   aucun commentaire qui la justifie ou l'annonce.
4. Ton objectif n'est PAS de produire le "meilleur Jenkinsfile absolu", mais le meilleur
   Jenkinsfile qui RESPECTE les choix du développeur.
` : (context.notes ? `Notes : ${context.notes}` : '');

// Bloc injecte SEULEMENT si un contexte d'erreur de build reel est fourni
// (voir webhooks.service.ts -> optimize()). Absent = comportement identique
// a avant (analyse statique normale, aucun changement).
const buildErrorBlock = buildError ? `
════════════════════════════════════════════════
ERREUR DE BUILD REELLE — PRIORITE ABSOLUE
════════════════════════════════════════════════
Le dernier build Jenkins a echoue avec cette erreur reelle, extraite du log console :
"${buildError}"

Priorise la correction de CETTE erreur precise. Les fichiers du projet (pom.xml, Dockerfile
— fournis plus loin dans ce message, section CONTEXTE PROJET) restent la SOURCE DE VERITE
pour determiner COMMENT corriger. Exemple : cette erreur mentionne 'cannot access mvnw' et
le contexte projet indique hasMvnw=false -> remplace ./mvnw par mvn. Ne corrige que ce qui
est coherent avec le contexte projet ET avec cette erreur reelle — n'invente rien de plus.
` : '';

// Rappel condensé réinjecté EN TOUTE FIN du message (contre le biais de récence).
const finalReminder = isRegen ? `

════════════════════════════════════════════════
RAPPEL FINAL — À VÉRIFIER AVANT DE RÉPONDRE
════════════════════════════════════════════════
Corrections ÉCARTÉES, INTERDITES dans ta réponse même si ce sont de bonnes pratiques : ${exclRefs}.
Avant de produire ton JSON, relis le Jenkinsfile que tu t'apprêtes à générer et confirme
qu'aucune de ces corrections écartées n'y figure — ni dans le code, ni dans un commentaire.` : '';

const systemPrompt = `Tu es un architecte CI/CD senior, expert Jenkins et DevSecOps (15 ans d'expérience).
Ta mission : analyser un Jenkinsfile et produire une version améliorée, plus propre, plus sûre et plus rapide.
Réponds UNIQUEMENT en JSON valide — pas de markdown, pas de backticks. Commence par { et termine par }.
N'écris JAMAIS de raisonnement, de liste de vérification ou de texte avant le JSON — même pour vérifier les règles ci-dessous : cette vérification est SILENCIEUSE, son résultat va directement dans le champ "summary" du JSON, jamais en texte libre.
LANGUE : tous les textes (summary, title, problem, recommendation, description) en FRANÇAIS professionnel. Le code reste tel quel.
RÈGLE D'ARRÊT — ERREURS REELLES SEULEMENT :
Tu ne signales et ne corriges QUE des erreurs RÉELLES et vérifiables : syntaxe Groovy
invalide, incohérence avec pom.xml/Dockerfile (version Java, nom du JAR, stage docker
sans Dockerfile), interpolation Groovy non échappée d'une variable credentials dans un
bloc sh (GString "...$VAR..." au lieu d'un shell single-quote '...$VAR...' — fuite
potentielle du secret dans les logs malgré withCredentials). Vérifie ces 4 catégories de façon exhaustive à chaque analyse, sans exception — mais
SILENCIEUSEMENT : ne décris jamais cette vérification, va directement à la sortie JSON. Tu n'inventes JAMAIS d'amélioration subjective ('tu pourrais ajouter
un timeout', 'tu pourrais paralléliser', 'ce serait mieux si...') sur un Jenkinsfile
qui est déjà valide et cohérent. Si le Jenkinsfile ne contient AUCUNE erreur réelle,
tu réponds exactement : 'Jenkinsfile conforme, aucune correction nécessaire' et tu
renvoies le fichier INCHANGÉ (identique caractère pour caractère). Ne modifie pas une
seule ligne dans ce cas. (Cette réponse reste un JSON valide au FORMAT EXACT plus bas :
summary="Jenkinsfile conforme, aucune correction nécessaire", issues=[], changes=[],
optimizedJenkinsfile=le fichier original strictement inchangé.)
RÈGLES D'ANALYSE — examine dans cet ordre :
1. SECURITE : credentials/tokens/mots de passe en clair (CRITIQUE), absence de withCredentials, images Docker en :latest ou sans tag, sh avec interpolation non échappée de variables Groovy (injection), permissions trop larges.
2. FIABILITE : absence de timeout global et par stage, pas de retry sur les étapes réseau, pas de post { always { cleanWs() } }, pas de post { failure }, stages sans when pertinent.
3. PERFORMANCE : scans sécurité séquentiels qui pourraient être parallèles (parallel {}), absence de cache Maven/npm, ordre non fail-fast (vérifications rapides d'abord), checkout redondants.
4. LISIBILITE : variables d'environnement dupliquées, blocs sh géants, absence de options { timestamps() }, stages mal nommés.
5. DEVSECOPS : ordre recommandé build → tests → SAST (Sonar) → dependency check → image build → scan image (Trivy) → deploy éphémère → DAST (ZAP) ; archivage des rapports. Ne suggère JAMAIS d'ajouter waitForQualityGate() ou un quality gate bloquant : cela nécessite un webhook SonarQube→Jenkins configuré côté infrastructure, invérifiable depuis le Jenkinsfile seul, et un pipeline peut rester bloqué indéfiniment si ce webhook n'est pas en place.
CONTRAINTE DE SÉLECTION — PRIORITÉ ABSOLUE sur toute bonne pratique :
- Si une liste de corrections ÉCARTÉES t'est fournie dans le message, tu ne dois JAMAIS réintroduire ces corrections, même si ce sont des bonnes pratiques DevSecOps standard. Une exclusion est un choix délibéré du développeur, pas un oubli à corriger. Cette contrainte l'emporte sur toutes les règles d'analyse ci-dessus.
RÈGLE SYNTAXE GROOVY (priorité absolue, prime sur la préservation du code existant) :
timestamps() n'est PAS une option valide. S'il apparaît dans options{}, tu DOIS le
retirer de options{} et envelopper les steps avec :
  INCORRECT :  options { timestamps() }
  CORRECT   :  stage('X') { steps { timestamps { sh '...' } } }
Un Jenkinsfile qui ne compile pas n'est PAS 'du code fonctionnel à préserver' — la
règle CONSERVE ne s'applique JAMAIS à une syntaxe invalide. Corrige-la toujours.
RÈGLES DE RÉÉCRITURE — impératives :
- CONSERVE tous les outils, stages, credentials IDs, URLs et webhooks existants. N'invente JAMAIS un credential ID, une URL ou un outil absent de l'original.
- Le fichier optimisé doit être COMPLET et directement utilisable (pas de "..." ni de sections omises).
- Chaque changement doit correspondre à une issue listée (traçabilité via ref).
- Commentaires français courts uniquement là où un choix mérite explication.
- Ne change rien sur les points déjà corrects.
RÈGLE DE CONFIANCE — n'affirme jamais comme un fait ce que tu ne peux pas vérifier depuis le Jenkinsfile fourni :
- Certaines recommandations dépendent d'informations EXTERNES que tu n'as pas : existence d'un tag précis d'image sur un registre (ex: aquasec/trivy:0.51.1 existe-t-il ?), plugin Jenkins réellement installé (ex: waitForQualityGate nécessite le plugin SonarQube + un webhook configuré), version d'un outil externe, config runtime de l'agent, secrets/credentials présents dans Jenkins.
- Pour CHAQUE issue de ce type, ajoute "needsConfirmation": true et "confirmationNote": "<quoi vérifier précisément et où>" (ex: "vérifier que le tag aquasec/trivy:0.51.1 existe sur Docker Hub avant merge").
- IMPORTANT — ne mets ce flag QUE si l'exactitude dépend vraiment d'une info externe non vérifiable. Une recommandation entièrement vérifiable depuis le Jenkinsfile (ajouter un timeout(), paralléliser des stages, ajouter timestamps(), passer un token via withCredentials, cleanWs()) ne porte PAS ce flag : mets alors "needsConfirmation": false et "confirmationNote": "". Ne marque pas tout par excès — un flag partout noierait le signal et le rendrait inutile.
FORMAT EXACT :
{"score":<0-100 du fichier ORIGINAL>,"summary":"<3-4 phrases ; mentionne s'il existe des points à confirmer par le développeur>","issues":[{"id":"JF-1","category":"SECURITE|FIABILITE|PERFORMANCE|LISIBILITE|DEVSECOPS","severity":"CRITIQUE|ELEVE|MOYEN|FAIBLE","title":"<une ligne>","problem":"<1-2 phrases>","recommendation":"<quoi faire>","lineHint":"<extrait ou numéro>","needsConfirmation":<true|false>,"confirmationNote":"<si true: quoi vérifier et où ; sinon chaîne vide>"}],"optimizedJenkinsfile":"<FICHIER COMPLET>","changes":[{"ref":"JF-1","description":"<modif appliquée>"}],"estimatedTimeSavingPercent":<0-60>,"confidence":<0.0-1.0>}`;

const userContent = `Analyse et optimise ce Jenkinsfile du projet "${projectName}".
Contexte : SonarQube, Trivy, OWASP Dependency-Check et ZAP disponibles ; backend de reporting sur le réseau Docker.
${buildErrorBlock}
${selectionBlock}
JENKINSFILE ORIGINAL :
\n\`\`\`groovy
${jenkinsfile}
\`\`\`${finalReminder}`;

return [{ json: { apiBody: { model:'claude-sonnet-4-6', max_tokens:16000, temperature:0, system:systemPrompt, messages:[{role:'user',content:userContent}] }, projectName, owner, repo, branch } }];

const response = $input.first().json;
const fail = (msg, raw) => [{ json: { success:false, error:'PARSE_ERROR', message:msg, raw:String(raw||'').substring(0,800) } }];
if (response.error) return [{ json: { success:false, error:response.error, message:response.message } }];
const content = response.content?.[0]?.text || '';
if (!content) return fail("Réponse vide de l'agent", JSON.stringify(response).substring(0,300));
let clean = content.replace(/```json\s*/gi,'').replace(/```\s*/gi,'').trim();
const s = clean.indexOf('{'), e = clean.lastIndexOf('}');
if (s === -1 || e === -1) return fail('Aucun JSON trouvé', clean);
try {
  const p = JSON.parse(clean.substring(s, e+1));
  if (!p.optimizedJenkinsfile || String(p.optimizedJenkinsfile).length < 30) return fail('Fichier optimisé absent', clean);
  p.issues = Array.isArray(p.issues) ? p.issues : [];
  p.changes = Array.isArray(p.changes) ? p.changes : [];
  const o = { CRITIQUE:0, ELEVE:1, MOYEN:2, FAIBLE:3 };
  p.issues.sort((a,b)=>(o[a.severity]??9)-(o[b.severity]??9));

  // ── POST-CHECK DÉTERMINISTE (régénération) ────────────────────────────────
  // Objectif : garantir l'invariant "aucune correction écartée ne réapparaît",
  // indépendamment de l'obéissance du LLM. Best-effort : couvre les corrections
  // "réflexe" les plus courantes via une carte concept→pattern. Une exclusion non
  // reconnue n'est pas auto-vérifiée (pas de faux positif), juste non couverte.
  let excluded = [];
  try { excluded = $('Webhook - Optimize').first().json.body?.selection?.excluded || []; } catch (_) { excluded = []; }

  const PATTERNS = [
    { keys:['timeout'],                                    re:/\btimeout\s*\(/,            label:'timeout()' },
    { keys:['cleanws','nettoyage du workspace','workspace'], re:/\bcleanWs\s*\(/,          label:'cleanWs()' },
    { keys:['retry','nouvelle tentative'],                 re:/\bretry\s*\(/,              label:'retry()' },
    { keys:['timestamps','horodatage'],                    re:/\btimestamps\s*\(/,         label:'timestamps()' },
    { keys:['parallel','parallél','parallelis','parallèl'], re:/\bparallel\s*\{/,          label:'parallel {}' },
    { keys:['withcredentials','credential','token en clair','secret en clair'], re:/\bwithCredentials\s*\(/, label:'withCredentials()' },
    { keys:['quality gate','qualitygate','waitforqualitygate'], re:/\bwaitForQualityGate\s*\(/, label:'waitForQualityGate()' },
    { keys:['archiv'],                                     re:/\barchiveArtifacts\s*\(/,   label:'archiveArtifacts()' },
  ];

  const jf = String(p.optimizedJenkinsfile);
  const violations = [];
  for (const iss of excluded) {
    const hay = `${iss.title||''} ${iss.recommendation||''}`.toLowerCase();
    for (const pat of PATTERNS) {
      if (pat.keys.some(k => hay.includes(k)) && pat.re.test(jf)) {
        violations.push({ ref: iss.ref || iss.id || '?', title: iss.title || '', pattern: pat.label });
        break; // une violation par issue écartée suffit
      }
    }
  }

  const selectionRespected = violations.length === 0;
  let projectContext = null;
  try { projectContext = $('Build Project Context').first().json.projectContext; } catch (_) {}
  return [{ json: {
    success:true,
    analyzedAt:new Date().toISOString(),
    selectionRespected,                                   // false → l'agent a désobéi
    selectionViolations: violations,                      // détail des exclusions réintroduites
    projectContext,                                        // contexte projet réellement utilisé pour enrichir le prompt (traçabilité)
    ...p
  } }];
} catch (err) { return fail('JSON invalide : '+err.message, clean); }

const body = $input.first().json.body || $input.first().json;

// Normalisation owner/repo (fix 404 : repo peut arriver en "owner/name")
let owner = String(body.owner || '').trim();
let repo  = String(body.repo  || '').trim();
if (repo.includes('/')) {
  const parts = repo.split('/').filter(Boolean);
  repo = parts.pop();
  if (!owner && parts.length) owner = parts.pop();
}

const filePath   = String(body.filePath || 'Jenkinsfile').trim();
const baseBranch = String(body.baseBranch || '').trim();

// Contrat agent 2 : le backend recharge le Jenkinsfile ORIGINAL depuis le
// stockage (jobId) et fournit les issues RETENUES / ECARTEES en objets complets.
const original = String(body.originalJenkinsfile || body.jenkinsfile || '').trim();
const retained = Array.isArray(body.retained) ? body.retained : [];
const excluded = Array.isArray(body.excluded) ? body.excluded : [];

if (!owner || !repo) {
  return [{ json: { error:'INVALID_INPUT', message:'owner et repo sont requis' } }];
}
if (original.length < 30) {
  return [{ json: { error:'INVALID_INPUT', message:'Jenkinsfile original introuvable (jobId invalide ?)' } }];
}
if (retained.length === 0) {
  return [{ json: { error:'NOTHING_TO_APPLY', message:'Aucune correction retenue : rien a appliquer' } }];
}

const ts = new Date().toISOString().replace(/[:.]/g,'-').substring(0,19);
const branchName = `ci/jenkinsfile-optimization-${ts}`;
return [{ json: {
  owner, repo, filePath, baseBranch, original, retained, excluded, branchName,
  commitMessage: 'ci: optimisation du Jenkinsfile par agent IA',
  prTitle: '\ud83e\udd16 Optimisation du Jenkinsfile (agent IA)',
  prBody: `Cette PR applique la version optimisee du Jenkinsfile generee par l'agent IA de la plateforme DevSecOps.\n\n> Generee automatiquement \u2014 a relire avant merge.`
} }];

