const pr = $input.first().json;
const branch = $('Prepare - Apply Body').first().json.branchName;
const result = { prUrl: pr.html_url || pr.url || '', prNumber: pr.number || null, branch };
return [{ json: {
  success: true,
  status: 'success',                 // -> callback backend
  result,
  prUrl: result.prUrl, prNumber: result.prNumber, branch,
  message: 'Pull Request creee avec succes'
} }];

const j = $input.first().json;
const violations = Array.isArray(j.selectionViolations) ? j.selectionViolations : [];
const blocked = violations.length > 0;                 // vient du gate (Parse Apply Output)
const message = j.message
  || (blocked ? 'Corrections ecartees reintroduites par l\'agent' : (j.error || 'Echec de creation de la PR'));
return [{ json: {
  success: false,
  status: blocked ? 'blocked' : 'failed',               // -> callback backend
  result: { message, violations },
  error: j.error || (blocked ? 'SELECTION_VIOLATION' : 'APPLY_ERROR'),
  message
} }];

const body = $input.first().json.body || $input.first().json;
const owner = String(body.owner || '').trim();
const repo  = String(body.repo  || '').trim();
const filePath = String(body.filePath || 'Jenkinsfile').trim();
const ref = String(body.ref || 'main').trim();
if (!owner || !repo) return [{ json: { error:'INVALID_INPUT', message:'owner et repo sont requis' } }];
return [{ json: { owner, repo, filePath, ref } }];

const gh = $input.first().json;
let decoded = '';
if (typeof gh.content === 'string' && gh.encoding === 'base64') {
  try { decoded = Buffer.from(gh.content.replace(/\n/g,''), 'base64').toString('utf-8'); } catch(e) {}
} else if (typeof gh.content === 'string') {
  decoded = gh.content;                          // déjà décodé par le node n8n
} else if (typeof gh.data === 'string') {
  decoded = gh.data;
}
if (!decoded || decoded.length < 10) {
  return [{ json: { success:false, error:'EMPTY_FILE', message:'Jenkinsfile vide ou introuvable — collez-le manuellement' } }];
}
return [{ json: { success:true, jenkinsfile:decoded, filePath:$('Prepare - Fetch Body').first().json.filePath, sha:gh.sha||'', source:'github' } }];

const j = $input.first().json;
let message = j.message || 'Fichier introuvable sur le dépôt';
if (j.error === undefined && j.status === undefined) message = 'Jenkinsfile introuvable — vérifiez owner/repo/branche ou collez-le manuellement';
return [{ json: { success:false, error:j.error||'FETCH_ERROR', message } }];

return [{ json: {
  jobId: $('Webhook - Optimize').first().json.body.jobId,
  status: 'error',
  reason: "Agent IA a \u00e9chou\u00e9 (rate limit / erreur API Anthropic)",
  detail: ($json.error && $json.error.message) ? $json.error.message : (String($json.error) || 'Erreur inconnue'),
}}];

return [{ json: {
  jobId: $('Webhook - Optimize').first().json.body.jobId,
  status: 'error',
  reason: "R\u00e9ponse de l'agent illisible (\u00e9chec de parsing JSON)",
  detail: ($json.error && $json.error.message) ? $json.error.message : (String($json.error) || 'Erreur de parsing inconnue'),
}}];

const d = $input.first().json;
const original = String(d.original || '');
const retained = Array.isArray(d.retained) ? d.retained : [];
const excluded = Array.isArray(d.excluded) ? d.excluded : [];

const fmtRet = retained.length
  ? retained.map(i => `- [${i.ref || i.id}] ${i.title || ''}\n    \u2192 ${i.recommendation || i.problem || ''}`).join('\n')
  : '- (aucune)';
const fmtExc = excluded.length
  ? excluded.map(i => `- [${i.ref || i.id}] ${i.title || ''}`).join('\n')
  : '- (aucune)';
const exclRefs = excluded.map(i => i.ref || i.id).join(', ') || '(aucune)';

const systemPrompt = `Tu es un architecte CI/CD senior (expert Jenkins, DevSecOps, 15 ans d'experience).
Ta mission : produire une version REECRITE d'un Jenkinsfile en appliquant EXACTEMENT et UNIQUEMENT
les corrections retenues par le developpeur, sans jamais en introduire d'autres.
Reponds UNIQUEMENT en JSON valide \u2014 pas de markdown, pas de backticks. Commence par { et termine par }.
LANGUE : les textes (description) en FRANCAIS. Le code Groovy reste tel quel.

REGLES IMPERATIVES :
1. Applique SEULEMENT les corrections RETENUES listees. Aucune autre modification.
2. Les corrections ECARTEES sont INTERDITES : ne les applique pas, ne les re-suggere pas, ne les
   mentionne pas dans un commentaire. Le developpeur les a rejetees consciemment, ce n'est PAS un oubli.
3. Meme si une correction ecartee est une bonne pratique standard (timeout, cleanWs, retry, quality gate,
   epinglage de version d'image, etc.), tu NE DOIS PAS l'ajouter. La reintroduire est une ERREUR.
4. ENCHEVETREMENT : si une correction RETENUE t'oblige a toucher un element lie a une correction ECARTEE
   (ex: "extraire l'image dans une variable" alors que "epingler la version" est ecartee), conserve la
   VALEUR ORIGINALE (ex: garde ':latest'), n'applique pas la partie ecartee.
5. CONSERVE tous les outils, stages, credentials IDs, URLs, webhooks existants. N'invente rien.
6. Le fichier doit etre COMPLET et directement utilisable (aucun "..." ni section omise).

FORMAT EXACT :
{"optimizedJenkinsfile":"<FICHIER COMPLET>","changes":[{"ref":"JF-1","description":"<modif appliquee>"}],"confidence":<0.0-1.0>}`;

const userContent = `Voici le Jenkinsfile ORIGINAL a reecrire.

CORRECTIONS RETENUES (a appliquer, et rien d'autre) :
${fmtRet}

CORRECTIONS ECARTEES (INTERDITES \u2014 ne jamais reintroduire, meme si ce sont de bonnes pratiques) :
${fmtExc}

JENKINSFILE ORIGINAL :
\n\`\`\`groovy
${original}
\`\`\`

RAPPEL FINAL avant de repondre : les corrections ecartees suivantes sont INTERDITES dans ta sortie \u2014
${exclRefs}. Relis le fichier que tu produis et confirme qu'aucune n'y figure (ni code, ni commentaire).`;

return [{ json: { apiBody: { model:'claude-sonnet-4-6', max_tokens:16000, temperature:0, system:systemPrompt, messages:[{role:'user',content:userContent}] } } }];

