if (response.error) { const em = response.message || (response.error && (response.error.message || (typeof response.error==='string'?response.error:JSON.stringify(response.error)))) || 'Erreur technique Apply Agent'; return [{ json: { success:false, gateOk:false, error:'AGENT_ERROR', message:String(em) } }]; }
const content = response.content?.[0]?.text || '';
if (!content) return fail("Reponse vide de l'agent de remediation", JSON.stringify(response).substring(0,300));
let clean = content.replace(/```json\s*/gi,'').replace(/```\s*/gi,'').trim();
const s = clean.indexOf('{'), e = clean.lastIndexOf('}');
if (s === -1 || e === -1) return fail('Aucun JSON trouve', clean);
let p;
try { p = JSON.parse(clean.substring(s, e+1)); }
catch (err) { return fail('JSON invalide : '+err.message, clean); }
if (!p.optimizedJenkinsfile || String(p.optimizedJenkinsfile).length < 30) return fail('Fichier optimise absent', clean);

// POST-CHECK DETERMINISTE : aucune correction ecartee ne doit reapparaitre.
// Best-effort sur les corrections "reflexe" a base d'appel de methode Groovy.
// (L'epinglage d'image :latest->version n'est pas couvert ici -> revue humaine.)
let excluded = [];
try { excluded = $('Prepare - Apply Body').first().json.excluded || []; } catch (_) {}
const PATTERNS = [
  { keys:['timeout'], re:/\btimeout\s*\(/, label:'timeout()' },
  { keys:['cleanws','nettoyage du workspace','workspace'], re:/\bcleanWs\s*\(/, label:'cleanWs()' },
  { keys:['retry','nouvelle tentative'], re:/\bretry\s*\(/, label:'retry()' },
  { keys:['timestamps','horodatage'], re:/\btimestamps\s*\(/, label:'timestamps()' },
  { keys:['parallel','parallel','parallelis'], re:/\bparallel\s*\{/, label:'parallel {}' },
  { keys:['withcredentials','credential','token en clair','secret'], re:/\bwithCredentials\s*\(/, label:'withCredentials()' },
  { keys:['quality gate','qualitygate','waitforqualitygate'], re:/\bwaitForQualityGate\s*\(/, label:'waitForQualityGate()' },
  { keys:['archiv'], re:/\barchiveArtifacts\s*\(/, label:'archiveArtifacts()' },
];
const jf = String(p.optimizedJenkinsfile);
const violations = [];
for (const iss of excluded) {
  const hay = `${iss.title||''} ${iss.recommendation||''}`.toLowerCase();
  for (const pat of PATTERNS) {
    if (pat.keys.some(k => hay.includes(k)) && pat.re.test(jf)) {
      violations.push({ ref: iss.ref || iss.id || '?', title: iss.title || '', pattern: pat.label });
      break;
    }
  }
}
const ok = violations.length === 0;
return [{ json: {
  success:true,
  gateOk: ok,
  selectionRespected: ok,
  selectionViolations: violations,
  optimizedJenkinsfile: jf,
  changes: Array.isArray(p.changes) ? p.changes : [],
  message: ok ? 'OK' : ('Corrections ecartees reintroduites : ' + violations.map(v=>v.ref+' ('+v.pattern+')').join(', '))
} }];

const prepared = $('Prepare - Optimizer Body').first().json;

// Selectionne le node qui a REELLEMENT tourne (OK ou Err) entre une paire.
// continueErrorOutput garantit qu'exactement un des deux tourne par execution
// -> exactement un des deux try reussit. Si les DEUX echouent, ce n'est PAS
// "fichier absent" (ca, c'est le role du node Err lui-meme de le dire) - c'est
// soit une erreur de cablage (nom de node incorrect apres un refactor), soit
// une anomalie continueErrorOutput qui ne devrait structurellement pas arriver.
// Dans les deux cas on le signale bruyamment plutot que de le confondre
// silencieusement avec "found:false" legitime.
function pick(okName, errName) {
  try { return $(okName).first().json; } catch (e1) {
    try { return $(errName).first().json; } catch (e2) {
      console.warn(`[Build Project Context] pick(): ni '${okName}' ni '${errName}' n'ont produit de donnee - erreur de cablage probable (nom de node incorrect) ou anomalie continueErrorOutput inattendue. Verifier le graphe WF4.`);
      return { found: false, content: '', _pickWiringError: true };
    }
  }
}
const pom     = pick('Format pom.xml OK', 'Format pom.xml Err');
const gradle  = pick('Format build.gradle OK', 'Format build.gradle Err');
const docker  = pick('Format Dockerfile OK', 'Format Dockerfile Err');
const mvnw    = pick('Format mvnw OK', 'Format mvnw Err');
const gradlew = pick('Format gradlew OK', 'Format gradlew Err');

let buildTool = 'unknown', javaVersion = null, packaging = 'jar';
let artifactId = null, version = null, finalName = null;
let isSpringBoot = false, hasTests = false;

if (pom.found) {
  buildTool = 'maven';
  const xml = pom.content;
  const xmlNoParent = xml.replace(/<parent>[\s\S]*?<\/parent>/, '');
  const grab = (tag) => {
    const m = xmlNoParent.match(new RegExp(`<${tag}>\\s*([^<]+?)\\s*</${tag}>`));
    return m ? m[1].trim() : null;
  };
  javaVersion = grab('java.version') || grab('maven.compiler.release')
             || grab('maven.compiler.target') || grab('maven.compiler.source');
  packaging = grab('packaging') || 'jar';
  artifactId = grab('artifactId');
  version = grab('version');
  finalName = grab('finalName');
  isSpringBoot = /spring-boot-maven-plugin/.test(xml);
  hasTests = /<scope>\s*test\s*<\/scope>/.test(xml) || /spring-boot-starter-test|junit|testng/i.test(xml);
} else if (gradle.found) {
  buildTool = 'gradle';
  const g = gradle.content;
  const srcCompat = g.match(/sourceCompatibility\s*=?\s*['"]?(?:JavaVersion\.VERSION_)?(\d+)/);
  javaVersion = srcCompat ? srcCompat[1] : null;
  isSpringBoot = /org\.springframework\.boot/.test(g);
  hasTests = /useJUnitPlatform|testImplementation/.test(g);
}

const artifactName = buildTool === 'maven'
  ? (finalName ? `${finalName}.${packaging}` : (artifactId && version ? `${artifactId}-${version}.${packaging}` : null))
  : null;

let hasDockerfile = false, dockerBaseJavaVersion = null, dockerCopySource = null;
if (docker.found) {
  hasDockerfile = true;
  const fromLines = [...docker.content.matchAll(/^FROM\s+(\S+)/gim)].map(m => m[1]);
  const lastFrom = fromLines[fromLines.length - 1] || '';
  const verMatch = lastFrom.match(/:[^\d]*?(\d{1,2})(?:[-.]|$)/) || lastFrom.match(/(\d{1,2})/);
  dockerBaseJavaVersion = verMatch ? verMatch[1] : null;
  const copyMatch = docker.content.match(/^COPY\s+(?:--from=\S+\s+)?(\S*\.(?:jar|war))\s+\S+/im);
  dockerCopySource = copyMatch ? copyMatch[1] : null;
}

const coherenceWarnings = [];
if (hasDockerfile && dockerBaseJavaVersion && javaVersion && Number(dockerBaseJavaVersion) < Number(javaVersion)) {
  coherenceWarnings.push(`Dockerfile FROM Java ${dockerBaseJavaVersion} but ${buildTool} compiles Java ${javaVersion} → UnsupportedClassVersionError`);
}
if (hasDockerfile && dockerCopySource && artifactName && !dockerCopySource.includes('*') && !dockerCopySource.includes(artifactName)) {
  coherenceWarnings.push(`Dockerfile COPY path (${dockerCopySource}) does not match real artifactName (${artifactName})`);
}
if (buildTool === 'maven' && !isSpringBoot && /spring-boot-starter/.test(pom.content || '')) {
  coherenceWarnings.push('spring-boot-maven-plugin missing but Spring Boot expected → non-executable jar');
}

const projectContext = {
  buildTool, javaVersion, packaging, artifactName, isSpringBoot,
  hasDockerfile, dockerBaseJavaVersion, dockerCopySource,
  dockerReadConfirmed: docker.readConfirmed !== false,
  hasMvnw: buildTool === 'maven' ? !!mvnw.found : false,
  hasGradlew: buildTool === 'gradle' ? !!gradlew.found : false,
  hasTests, coherenceWarnings,
};

const apiBody = JSON.parse(JSON.stringify(prepared.apiBody));

const rulesBlock = `

CONTEXTE PROJET (extrait de pom.xml/build.gradle/Dockerfile — SOURCE DE VERITE,
ne JAMAIS l'inverser : aligne le Jenkinsfile sur ces fichiers, jamais l'inverse) :
${JSON.stringify(projectContext, null, 2)}

REGLES D'UTILISATION DE CE CONTEXTE — STRICTES, prioritaires sur les regles generales :
REGLE DE PRIORITE ABSOLUE (prime sur TOUTE autre regle, y compris JF-7 PERFORMANCE) :
Le nombre de stages et leurs noms en SORTIE doivent etre IDENTIQUES a l'ENTREE, a la
seule exception de la regle 3 ci-dessous (retrait d'un stage docker si hasDockerfile=false).
Toute regle de performance (dont JF-7 parallel{}) ne peut REORGANISER ou fusionner que des
stages DEJA EXISTANTS - jamais en creer un nouveau, jamais en introduire un wrapper qui
apparait comme un stage supplementaire (ex: un stage "Security Scans" qui n'existait pas et
qui englobe Trivy Scan + OWASP Dependency Check est INTERDIT, meme si JF-7 le suggere).
Si une optimisation JF-7 exigerait d'ajouter un stage, NE PAS l'appliquer : laisse les
stages concernes tels quels, sequentiels, sans les regrouper dans un nouveau stage.
Aucune suppression de stage pour motif de "redondance" (seule exception : regle 3).
Tu ne fais que MODIFIER le contenu de stages existants.

AUTO-FIX autorise (seulement si le champ correspondant n'est pas null) :
  1. version du tool JDK -> doit correspondre a projectContext.javaVersion
  2. chemin archiveArtifacts -> doit correspondre a projectContext.artifactName
  3. si hasDockerfile === false ET dockerReadConfirmed === true -> retirer les
     stages docker build/push (absence REELLEMENT confirmee par GitHub, pas une
     lecture ratee). Si dockerReadConfirmed === false, NE RETIRE AUCUN stage
     docker/trivy/scan, meme si hasDockerfile apparait false -> traite l'info
     comme INCONNUE. Un stage de securite ne se supprime jamais sur une panne.
  4. si hasMvnw === true -> utiliser './mvnw' (+ 'sh "chmod +x mvnw"' avant) ;
     si buildTool === 'gradle' et hasGradlew === true -> utiliser './gradlew'
     Si hasMvnw === false ET le Jenkinsfile utilise deja './mvnw' ou
     'chmod +x mvnw' -> remplace-les par 'mvn' (un tool Maven est configure
     dans Jenkins). Un wrapper appele mais absent du depot fait echouer le
     build (chmod: cannot access 'mvnw': No such file or directory).
  5. corriger toute erreur de syntaxe Groovy visible dans le Jenkinsfile fourni —
     en particulier timestamps() : verifie la syntaxe Declarative Pipeline reelle
     avant de le deplacer, ne le laisse jamais dans un bloc qui ne compile pas
REPORT-ONLY — ne JAMAIS editer le Jenkinsfile pour ces cas, seulement les lister :
  - Dockerfile base Java < projectContext.javaVersion
  - Dockerfile COPY ne correspond pas a artifactName
  - spring-boot-maven-plugin manquant alors que Spring Boot est utilise
SECURITE :
  - champ null/unknown -> ne touche PAS la ligne Jenkinsfile concernee
  - n'invente JAMAIS une valeur absente de projectContext ou du Jenkinsfile original
  - ne modifie et ne renvoie QUE le Jenkinsfile
  - preserve tous les stages qui fonctionnent deja
SORTIE — ajoute ces 2 lignes en commentaire, en TETE du Jenkinsfile optimise :
  // [AUTO-FIXED]: <changements appliques via les regles 1-5, ou "aucun">
  // [WARNING]: <incoherences detectees mais non corrigees (REPORT-ONLY), ou "aucune">`;

apiBody.messages[0].content += rulesBlock;

return [{ json: { ...prepared, apiBody, projectContext } }];

